package win32

import (
	"syscall"
	"unsafe"
)

func StructArg[T any](v T) (x uintptr) {
	if unsafe.Sizeof(v) > unsafe.Sizeof(x) {
		panic("win32: by-value struct is too large to pass in a register")
	}
	*(*T)(unsafe.Pointer(&x)) = v
	return x
}

// Following code was copied from code generated by `mkwinsyscall` tool.

// Do the interface allocations only once for common
// Errno values.
const (
	errnoERROR_IO_PENDING = 997
)

var (
	errERROR_IO_PENDING error = syscall.Errno(errnoERROR_IO_PENDING)
	errERROR_EINVAL     error = syscall.EINVAL
)

// errnoErr returns common boxed Errno values, to prevent
// allocations at runtime.
func errnoErr(e syscall.Errno) error {
	switch e {
	case 0:
		return errERROR_EINVAL
	case errnoERROR_IO_PENDING:
		return errERROR_IO_PENDING
	}
	// TODO: add more here, after collecting data on the common
	// error values see on Windows. (perhaps when running
	// all.bat?)
	return e
}
